metadata-container:
.markdown-source-view.mod-cm6 .metadata-container { container-type: inline-size; }
@container (max-width: 320px) {
 .markdown-source-view.mod-cm6 .metadata-property { flex-direction: column; gap: 1px; padding-block: 6px; }
 .markdown-source-view.mod-cm6 .metadata-property-key { flex-basis: auto; width: 100%; max-width: none; min-height: 20px; font-size: 10px; }
 .markdown-source-view.mod-cm6 .metadata-property-value { width: 100%; }
}

metadata-count:
.markdown-source-view.mod-cm6 .metadata-container { counter-reset: done; }
.markdown-source-view.mod-cm6 .metadata-property:has(input:checked) { counter-increment: done; }
.markdown-source-view.mod-cm6 .metadata-container::after { content: "Отмечено: " counter(done); display: block; font-size: 11px; color: var(--text-accent); margin-top: 10px; }

metadata-grid-many:
.markdown-source-view.mod-cm6 .metadata-container { container-type: inline-size; }
.markdown-source-view.mod-cm6 .metadata-properties { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 10px; }
.markdown-source-view.mod-cm6 .metadata-property { flex-direction: column; }
.markdown-source-view.mod-cm6 .metadata-property-key { width: 100%; max-width: none; flex-basis: auto; }
.markdown-source-view.mod-cm6 .metadata-property-value { width: 100%; }
@container (min-width: 330px) { .markdown-source-view.mod-cm6 .metadata-properties { grid-template-columns: repeat(3,minmax(0,1fr)); } }
@container (min-width: 440px) { .markdown-source-view.mod-cm6 .metadata-properties { grid-template-columns: repeat(4,minmax(0,1fr)); } }

metadata-hover-tools:
@media (hover: hover) and (pointer: fine) {
  .markdown-source-view.mod-cm6 .metadata-container:not(:hover):not(:focus-within) :is(.metadata-properties-title, .metadata-add-button, .multi-select-pill-remove-button) { opacity: 0; }
  .markdown-source-view.mod-cm6 :is(.metadata-properties-title, .metadata-add-button, .multi-select-pill-remove-button) { transition: opacity .15s ease; }
}

metadata-leaders:
.markdown-source-view.mod-cm6 .metadata-property-key { flex-basis: 45%; width: 45%; }
.markdown-source-view.mod-cm6 .metadata-property-key::after { content: ""; flex: 1; min-width: 8px; align-self: center; border-bottom: 1px dotted var(--text-muted); margin-left: 3px; }
.markdown-source-view.mod-cm6 .metadata-property-icon { display: none; }

metadata-long:
.markdown-source-view.mod-cm6 .metadata-property { align-items: flex-start; }
.markdown-source-view.mod-cm6 .metadata-property-value { min-width: 0; }
.markdown-source-view.mod-cm6 .metadata-input-longtext { white-space: pre-wrap; overflow-wrap: anywhere; }

metadata-paper:
.markdown-source-view.mod-cm6 { --metadata-label-text-color: var(--text-muted); --metadata-input-font-size: 14px; }
.markdown-source-view.mod-cm6 .metadata-property-icon { display: none; }
.markdown-source-view.mod-cm6 .metadata-property-value { font-family: Georgia, serif; }
.markdown-source-view.mod-cm6 .metadata-properties-heading { font-weight: 400; }

metadata-roles:
.markdown-source-view.mod-cm6 .metadata-property[data-property-key="status"] { border-left: 3px solid var(--color-orange); }
.markdown-source-view.mod-cm6 .metadata-property[data-property-key="deadline"] { border-left: 3px solid var(--color-blue); }
.markdown-source-view.mod-cm6 .metadata-property[data-property-key="internal_id"] .metadata-property-value { font-family: var(--font-monospace); }
.markdown-source-view.mod-cm6 .metadata-property[data-property-key="cost"] input { font-variant-numeric: tabular-nums; text-align: right; }

metadata-sections:
.markdown-source-view.mod-cm6 .metadata-property:is([data-property-key="author"],[data-property-key="status"]) { display: grid; grid-template-columns: var(--metadata-label-width) minmax(0,1fr); }
.markdown-source-view.mod-cm6 .metadata-property:is([data-property-key="author"],[data-property-key="status"])::before { grid-column: 1 / -1; padding: 9px 5px 5px; font-size: 10px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; color: var(--text-accent); border-top: 1px solid var(--background-modifier-border); }
.markdown-source-view.mod-cm6 [data-property-key="author"]::before { content: "Источник"; }
.markdown-source-view.mod-cm6 [data-property-key="status"]::before { content: "Работа"; }

metadata-types:
.markdown-source-view.mod-cm6 input[type="date"] { font-family: var(--font-monospace); color: var(--color-blue); }
.markdown-source-view.mod-cm6 input[type="number"] { font-variant-numeric: tabular-nums; text-align: right; }
.markdown-source-view.mod-cm6 input[type="checkbox"] { accent-color: var(--color-green); }

metadata-wide-field:
.markdown-source-view.mod-cm6 .metadata-properties { display: grid; grid-template-columns: repeat(auto-fit,minmax(min(100%,15rem),1fr)); gap: 8px 20px; }
.markdown-source-view.mod-cm6 .metadata-property { min-width: 0; }
.markdown-source-view.mod-cm6 .metadata-property[data-property-key="description"] { grid-column: 1 / -1; border-top: 1px solid var(--background-modifier-border); padding-top: 8px; }

metadata-wrap-pills:
.markdown-source-view.mod-cm6 .multi-select-container { flex-wrap: wrap; gap: 6px; }
.markdown-source-view.mod-cm6 .multi-select-pill { max-width: 100%; border-radius: 20px; }
.markdown-source-view.mod-cm6 .multi-select-pill-content { overflow-wrap: anywhere; }

metadata-yaml-card:
.markdown-source-view.mod-cm6 .cm-line:has(.cm-hmd-frontmatter) { background: var(--background-secondary); border-inline: 1px solid var(--background-modifier-border); padding-inline: 10px; }
.markdown-source-view.mod-cm6 .cm-line:has(.cm-def):not(.cm-line + .cm-line) { border-top: 1px solid var(--background-modifier-border); border-radius: 8px 8px 0 0; }
.markdown-source-view.mod-cm6 .cm-line:has(.cm-def):not(:has(+ .cm-line .cm-hmd-frontmatter)) { border-bottom: 1px solid var(--background-modifier-border); border-radius: 0 0 8px 8px; }

metadata-yaml-tokens:
.markdown-source-view.mod-cm6 .cm-hmd-frontmatter.cm-atom { color: var(--color-blue); font-weight: 650; }
.markdown-source-view.mod-cm6 .cm-hmd-frontmatter.cm-string { color: var(--color-green); }
.markdown-source-view.mod-cm6 .cm-hmd-frontmatter.cm-number { color: var(--color-orange); }
.markdown-source-view.mod-cm6 .cm-hmd-frontmatter.cm-comment { color: var(--text-muted); font-style: italic; }
.markdown-source-view.mod-cm6 .cm-hmd-frontmatter.cm-def { color: var(--text-muted); }

